package Controlstatement;



public class task8 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String day="1";

	switch (day) {
	case "one":System.out.println("SUN");
	break;
	case "two":System.out.println("MON");
	break;
	case "three":System.out.println("TUE");
	break;
	case "four":System.out.println("WED");
	break;
	case "five":System.out.println("THU");
	break;
	case "six":System.out.println("FRI");
	break;
	case "seven":System.out.println("SAT");
	break;
	default : System.out.println("invalid value");
	}
	
	}
}
